"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["52077"],{39280(e,t,a){a.d(t,{Ay:()=>r,RM:()=>i});var n=a(74848),o=a(28453);let i=[];function s(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"the-great-mao-and-baldy-chiang",children:"The Great Mao and Baldy Chiang"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2008/1/7 18:23:48"}),"\n"]}),"\n",(0,n.jsxs)("div",{style:{color:"#FF0000",fontWeight:"500",fontSize:"18px",textAlign:"left",lineHeight:"180%"},children:[(0,n.jsx)(t.p,{children:"In truth, Baldy Chiang has absolutely no right to be compared with the Great Mao. What is politics? The winner takes all. Baldy Chiang lost so completely to the Great Mao that he didn't even have his underwear left. He had to plunder national treasures and smuggle gold, surviving under the shelter of his American master. Tell me, what right does he have to compare with the Great Mao?"}),(0,n.jsx)(t.p,{children:'Don\'t use drivel like "character" or "morality" to evaluate political figures. The greatest virtue of a political figure is victory. Before the Great Mao, Baldy Chiang doesn\'t even count as a cockroach.'}),(0,n.jsx)(t.p,{children:"Actually, stories about the Great Mao and Baldy Chiang are absurdly common in Chinese history. Every dynasty has similar stories before its founding. By comparison, Baldy Chiang is the most pathetic of the lot. He can't even compare to Yang Guang, and is certainly no match for Chen Youliang \u2014 and as for Xiang Yu, that's entirely beyond his league. Probably the only one he can be compared to is the Second Emperor of Qin."}),(0,n.jsx)(t.p,{children:"There is never anything new in history. Stories isomorphic to Zhu Yuanzhang vs. Chen Youliang and Liu Bang vs. Xiang Yu keep occurring \u2014 the plots are roughly the same, nothing remarkable."}),(0,n.jsx)(t.p,{children:'Both the Great Mao and Baldy Chiang started from nothing. The difference is that Baldy Chiang\'s "starting from nothing" began with latching onto a big patron, and he never changed course, ultimately finishing his farce under the wing of his American daddy. The Great Mao, from the outset, was destined to have no big patron to latch onto \u2014 and this is precisely what enabled him to unleash his full potential without restraint.'}),(0,n.jsx)(t.p,{children:"You can't become a big shot by latching onto one. All you become is a lackey. To become the biggest shot, the ultimate badass, the only way is to unleash your own energy to the fullest and defeat every big shot out there. Then you are the biggest of them all, the most formidable of all."}),(0,n.jsx)(t.p,{children:"For individuals, this may not matter much \u2014 people don't necessarily need to become the most formidable. Being human, one should aim to become the happiest, most carefree, most at ease, most self-actualized person. But for a nation, especially a great nation, this is supremely important."}),(0,n.jsx)(t.p,{children:"For a nation like China, given its geopolitical history, if it does not become super first-rate, it is destined to be carved up \u2014 because all the first-rate powers will want to slaughter and divide you first before they can rest easy."}),(0,n.jsx)(t.p,{children:"Some people resent the Great Mao for exploiting the Anti-Japanese War period to turn the tables. In truth, didn't Baldy Chiang also try to exploit it? He just didn't have the ability. He played a much better hand into oblivion \u2014 if that's not worthless, what is?"}),(0,n.jsx)(t.p,{children:"Baldy Chiang, that useless pastry \u2014 let's not waste more words. Of course, he had his contributions too. At least he consolidated the various petty warlords, so that the Great Mao could sweep them all up in one pot. Come to think of it, that's about all Baldy Chiang was good for."})]})]})}function r(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(s,{...e})}):s(e)}},74476(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>r,contentTitle:()=>h,toc:()=>d,assets:()=>l});var n=JSON.parse('{"id":"essays/maoandjiang","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/essays/maoandjiang.md","sourceDirName":"essays","slug":"/essays/maoandjiang","permalink":"/en/essays/maoandjiang","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maoandjiang","title":"","hide_table_of_contents":true,"sidebar_label":"Uncle Mao and Baldy Chiang (2008/1/7 18:23:48)"},"sidebar":"essaysSidebar","previous":{"title":"What the May Fourth Brats\' Western Daddy Admires as \\"Human Nature\\" (2007/12/25 20:32:12)","permalink":"/en/essays/westernhumanity"},"next":{"title":"People of Different Levels (2008/2/2 9:13:24)","permalink":"/en/essays/humanlevels"}}'),o=a(74848),i=a(28453),s=a(39280);let r={id:"maoandjiang",title:"",hide_table_of_contents:!0,sidebar_label:"Uncle Mao and Baldy Chiang (2008/1/7 18:23:48)"},h,l={},d=[...s.RM];function c(e){return(0,o.jsx)(s.Ay,{})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453(e,t,a){a.d(t,{R:()=>s,x:()=>r});var n=a(96540);let o={},i=n.createContext(o);function s(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);